"use client";
import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";
import { sliceTransitions, useLatency, type LatencyPhase } from "../hooks/latency";

/**
 * The states an async button can be in. They are the shared latency states
 * (hooks/latency.ts), minus the two a button has no use for: it never draws
 * a skeleton and it cannot be cancelled.
 */
export type AsyncButtonState = Extract<LatencyPhase, "idle" | "pending" | "slow" | "success" | "error">;

export type AsyncButtonEvent = "START" | "SLOW" | "RESOLVE" | "REJECT" | "RESET";

const BUTTON_STATES = ["idle", "pending", "slow", "success", "error"] as const satisfies readonly AsyncButtonState[];
const BUTTON_EVENTS = ["START", "SLOW", "RESOLVE", "REJECT", "RESET"] as const satisfies readonly AsyncButtonEvent[];

/**
 * Every legal transition, read straight from the shared latency machine.
 * Anything not listed is ignored, so a second press while pending cannot
 * start a second request and a late result cannot move a button that has
 * already reset.
 */
export const ASYNC_BUTTON_TRANSITIONS = sliceTransitions(BUTTON_STATES, BUTTON_EVENTS);

export const asyncButtonReducer = (state: AsyncButtonState, event: AsyncButtonEvent): AsyncButtonState =>
  ASYNC_BUTTON_TRANSITIONS[state][event] ?? state;

export interface AsyncButtonLabels {
  idle: string;
  pending: string;
  slow: string;
  success: string;
  error: string;
}

const DEFAULT_LABELS: AsyncButtonLabels = {
  idle: "Save changes",
  pending: "Saving",
  slow: "Still working, this is taking longer than usual",
  success: "Saved",
  error: "Failed. Press to try again",
};

export interface AsyncButtonProps {
  /** The work. Resolve for success, reject (or throw) for failure. */
  onPress: () => Promise<unknown>;
  /** Text for each state. Missing keys fall back to the defaults. */
  labels?: Partial<AsyncButtonLabels>;
  /** How long a request runs before the button says it is slow. */
  slowAfterMs?: number;
  /** How long "success" stays before the button returns to idle. */
  successHoldMs?: number;
  /** Force reduced motion on or off. Leave undefined to follow the system setting. */
  reducedMotion?: boolean;
  /** Called on every state change, with the event that caused it. */
  onStateChange?: (next: AsyncButtonState, event: AsyncButtonEvent) => void;
  className?: string;
}

const REDUCED_QUERY = "(prefers-reduced-motion: reduce)";

const subscribeReduced = (notify: () => void) => {
  const query = window.matchMedia(REDUCED_QUERY);
  query.addEventListener("change", notify);
  return () => query.removeEventListener("change", notify);
};

/** The system setting, kept live. The server snapshot is false, so first paint matches on both sides. */
export const useSystemReducedMotion = (): boolean =>
  useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(REDUCED_QUERY).matches,
    () => false
  );

const TINT: Record<AsyncButtonState, string> = {
  idle: "255,255,255",
  pending: "140,160,255",
  slow: "255,196,110",
  success: "130,220,170",
  error: "255,130,130",
};

/**
 * A button that tells the truth about waiting. It stays focusable while it
 * works, ignores presses it cannot honour, says out loud when a request is
 * slow, and offers a retry on failure. The visible state, the screen-reader
 * announcement and the colour all come from one small state machine.
 *
 * With reduced motion the moving progress bar becomes a still, partly filled
 * bar and the colour change is instant; the words carry the same information.
 *
 * @example
 * <AsyncButton onPress={() => fetch("/api/save", { method: "POST" })} />
 */
export const AsyncButton = ({
  onPress,
  labels,
  slowAfterMs = 1200,
  successHoldMs = 1600,
  reducedMotion,
  onStateChange,
  className = "",
}: AsyncButtonProps) => {
  const systemReduced = useSystemReducedMotion();
  const reduced = reducedMotion ?? systemReduced;
  const text = { ...DEFAULT_LABELS, ...labels };

  const onStateChangeRef = useRef(onStateChange);
  useEffect(() => {
    onStateChangeRef.current = onStateChange;
  }, [onStateChange]);

  const run = useCallback(() => Promise.resolve().then(onPress), [onPress]);
  const { phase, start } = useLatency({
    run,
    slowAfterMs,
    successHoldMs,
    onEvent: ({ event, to }) => onStateChangeRef.current?.(to as AsyncButtonState, event as AsyncButtonEvent),
  });
  const state = phase as AsyncButtonState;
  const press = start;

  const busy = state === "pending" || state === "slow";
  const tint = TINT[state];
  const label = text[state];

  return (
    <div className={`inline-flex flex-col items-stretch gap-2 ${className}`}>
      <style>{`
        @keyframes prism-async-slide { from { transform: translateX(-100%); } to { transform: translateX(250%); } }
      `}</style>
      <button
        type="button"
        onClick={press}
        aria-busy={busy}
        aria-disabled={busy}
        data-state={state}
        className="relative overflow-hidden rounded-xl px-6 py-3 text-sm font-medium text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-white/70 focus-visible:ring-offset-2 focus-visible:ring-offset-black"
        style={{
          background: `rgba(${tint},${state === "idle" ? 0.08 : 0.16})`,
          border: `1px solid rgba(${tint},${state === "idle" ? 0.2 : 0.5})`,
          cursor: busy ? "progress" : "pointer",
          transition: reduced ? "none" : "background 240ms, border-color 240ms",
        }}
      >
        <span className="relative z-10 block text-center">{label}</span>
        {busy && (
          <span
            aria-hidden
            className="absolute bottom-0 left-0 h-[3px]"
            style={
              reduced
                ? { width: state === "slow" ? "75%" : "40%", background: `rgb(${tint})` }
                : {
                    width: "40%",
                    background: `rgb(${tint})`,
                    animation: `prism-async-slide ${state === "slow" ? 2400 : 1100}ms linear infinite`,
                  }
            }
          />
        )}
      </button>
      {/* One polite announcement per state change; the visible label can be longer. */}
      <span role="status" aria-live="polite" className="sr-only">
        {state === "idle" ? "" : text[state]}
      </span>
    </div>
  );
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";

/**
 * Latency states: one honest lifecycle for anything that waits on a request.
 *
 * It is a state, not a component. The async button and the loading region
 * both run on it, and anything else that waits (a select that fetches its
 * options, a search box, a save bar) can take the same hook and get the same
 * timing rules for free:
 *
 * - pending: a request is out but under the skeleton threshold, so nothing
 *   new is drawn. A fast response never flashes a placeholder.
 * - skeleton: it has passed that threshold (only if you ask for one).
 * - slow: it has taken long enough that the interface should say so.
 * - success / error / cancelled: settled. START runs it again, RESET clears it.
 */
/** Under this, show nothing new: a fast response never flashes a placeholder. Shared by every waiting surface. */
export const QUIET_MS = 400;
/** Past this with no progress, say it is slow and offer a way out. */
export const SLOW_MS = 2000;

export type LatencyPhase = "idle" | "pending" | "skeleton" | "slow" | "success" | "error" | "cancelled";

export type LatencyEvent = "START" | "SHOW_SKELETON" | "SLOW" | "RESOLVE" | "REJECT" | "CANCEL" | "RESET";

/** Every legal transition. Anything not listed is ignored, so a late result cannot move a settled state. */
export const LATENCY_TRANSITIONS: Record<LatencyPhase, Partial<Record<LatencyEvent, LatencyPhase>>> = {
  idle: { START: "pending" },
  pending: { SHOW_SKELETON: "skeleton", SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  skeleton: { SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  slow: { RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  success: { START: "pending", RESET: "idle" },
  error: { START: "pending", RESET: "idle" },
  cancelled: { START: "pending", RESET: "idle" },
};

export const latencyReducer = (state: LatencyPhase, event: LatencyEvent): LatencyPhase =>
  LATENCY_TRANSITIONS[state][event] ?? state;

/**
 * The part of the machine one component uses: only these phases, reached
 * only by these events. A component that never shows a skeleton or never
 * cancels draws its own machine from this, and it is still the shared one.
 */
export const sliceTransitions = <P extends LatencyPhase, E extends LatencyEvent>(phases: readonly P[], events: readonly E[]) =>
  Object.fromEntries(
    phases.map((from) => [
      from,
      Object.fromEntries(
        Object.entries(LATENCY_TRANSITIONS[from]).filter(
          ([event, to]) => events.includes(event as E) && phases.includes(to as P)
        )
      ),
    ])
  ) as Record<P, Partial<Record<E, P>>>;

export const isBusy = (phase: LatencyPhase) => phase === "pending" || phase === "skeleton" || phase === "slow";

export interface LatencyLogEntry {
  /** Milliseconds since the request started (0 for START). */
  atMs: number;
  event: LatencyEvent;
  from: LatencyPhase;
  to: LatencyPhase;
}

export interface LatencyOptions<T> {
  /** The request. Honour `signal` if you can; late results are ignored either way. */
  run: (signal: AbortSignal) => Promise<T>;
  /** Show a skeleton after this long. Leave undefined to never show one. */
  skeletonAfterMs?: number;
  /** Say it is slow after this long. */
  slowAfterMs?: number;
  /** Return to idle this long after success. Leave undefined to stay on success. */
  successHoldMs?: number;
  /** Every real state change, with time since the request started. */
  onEvent?: (entry: LatencyLogEntry) => void;
}

/**
 * Run a request through the latency states.
 *
 * @example
 * const { phase, start } = useLatency({ run: (signal) => fetch("/api", { signal }), slowAfterMs: 1500 });
 */
export const useLatency = <T>({ run, skeletonAfterMs, slowAfterMs = SLOW_MS, successHoldMs, onEvent }: LatencyOptions<T>) => {
  const [phase, dispatch] = useReducer(latencyReducer, "idle");
  const phaseRef = useRef<LatencyPhase>("idle");
  const [data, setData] = useState<{ value: T } | null>(null);
  const [error, setError] = useState("");
  const [elapsedS, setElapsedS] = useState(0);

  const requestId = useRef(0);
  const startedAt = useRef(0);
  const timers = useRef<number[]>([]);
  const ticker = useRef<number | null>(null);
  const controller = useRef<AbortController | null>(null);
  const mounted = useRef(true);
  const onEventRef = useRef(onEvent);
  useEffect(() => {
    onEventRef.current = onEvent;
  }, [onEvent]);

  const stopTimers = () => {
    timers.current.forEach((t) => window.clearTimeout(t));
    timers.current = [];
    if (ticker.current !== null) window.clearInterval(ticker.current);
    ticker.current = null;
  };

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      stopTimers();
      controller.current?.abort();
    };
  }, []);

  /** Dispatch only legal events, and report real changes. */
  const send = useCallback((event: LatencyEvent) => {
    const from = phaseRef.current;
    const to = latencyReducer(from, event);
    if (to === from) return false;
    phaseRef.current = to;
    dispatch(event);
    const atMs = event === "START" ? 0 : Math.round(performance.now() - startedAt.current);
    onEventRef.current?.({ atMs, event, from, to });
    return true;
  }, []);

  const start = useCallback(() => {
    if (isBusy(phaseRef.current)) return;
    stopTimers();
    startedAt.current = performance.now();
    if (!send("START")) return;
    const id = ++requestId.current;
    const ctl = new AbortController();
    controller.current = ctl;
    const live = () => mounted.current && id === requestId.current;

    if (skeletonAfterMs !== undefined) {
      timers.current.push(window.setTimeout(() => live() && send("SHOW_SKELETON"), skeletonAfterMs));
    }
    timers.current.push(
      window.setTimeout(() => {
        if (!live()) return;
        send("SLOW");
        const tick = () => setElapsedS(Math.floor((performance.now() - startedAt.current) / 1000));
        tick();
        ticker.current = window.setInterval(tick, 250);
      }, slowAfterMs)
    );

    Promise.resolve()
      .then(() => run(ctl.signal))
      .then(
        (value) => {
          if (!live()) return;
          stopTimers();
          setData({ value });
          send("RESOLVE");
          if (successHoldMs !== undefined) {
            timers.current.push(window.setTimeout(() => live() && send("RESET"), successHoldMs));
          }
        },
        (err: unknown) => {
          if (!live()) return;
          stopTimers();
          setError(err instanceof Error ? err.message : "Request failed");
          send("REJECT");
        }
      );
  }, [run, send, skeletonAfterMs, slowAfterMs, successHoldMs]);

  const cancel = useCallback(() => {
    if (!isBusy(phaseRef.current)) return;
    requestId.current++; // a late result can no longer move the state
    stopTimers();
    controller.current?.abort();
    send("CANCEL");
  }, [send]);

  const reset = useCallback(() => {
    requestId.current++;
    stopTimers();
    send("RESET");
  }, [send]);

  return { phase, busy: isBusy(phase), data, error, elapsedS, start, cancel, reset };
};
